// Reads the incoming webhook payload and holds all NON-SECRET configuration.
// Secrets (API keys, tokens) live in n8n credentials, never in this workflow.
const body = $json.body || $json;

const config = {
  // --- Quickbase --- (app buskqh26r)
  quickbaseRealmHost: 'byrdsonservices.quickbase.com',
  quickbaseTableId: 'bv32ejcgp',
  requiredBondThreshold: 50000,
  // --- App callback used for blob cleanup (DELETE /api/blob/delete) ---
  appBaseUrl: 'https://your-app.vercel.app',
  // --- Federal screening endpoints ---
  samUrl: 'https://api.sam.gov/entity-information/v4/exclusions',
  cslUrl: 'https://data.trade.gov/consolidated_screening_list/v1/search',
  // --- Quickbase field IDs (FIDs), mapped to the live table bv32ejcgp. ---
  fieldMap: {
    companyName: 6, trade: 7, entityType: 8, ownerName: 9, ein: 10,
    licenseNumber: 11, dacoReg: 12, streetAddress: 13, city: 14, state: 16,
    zip: 17, municipio: 15, yearsInBusiness: 18, revenue: 19, activeCrews: 20,
    bondSingle: 31, canMeetVolume: 27, hasLineOfCredit: 28, bonded: 30,
    contactName: 21, contactEmail: 22, contactPhone: 23,
    accountingName: 24, accountingEmail: 25, accountingPhone: 26,
    signers: 47, signerCount: 48, digitalSignatureName: 45, signerTitle: 46,
    personalGuarantee: 43, executedAt: 44, status: 59,
    // screening / scoring inputs. NOTE: "Disqualifier Flag" (41), "Vetting
    // Score" (57), and "Recommendation" (58) are Quickbase FORMULA fields — they
    // are derived by Quickbase and must NOT be written here.
    samExclusionHit: 39, ofacHit: 40,
    msaDigitallySigned: 42, financialsUploaded: 29, cfseCurrent: 33,
    meetsInsuranceLimits: 34, verifiedReferences: 35, entityStanding: 36,
    dacoComplaints: 37, materialLawsuits: 38, screeningIncomplete: 70,
  },
  // File-attachment FIDs, keyed by the upload key from the intake form.
  fileFieldMap: {
    suri: 50, crim: 51, patenteAsume: 52, coi: 53, cfse: 54, daco: 55,
    financials: 56,
  },
};

return [{ json: { body, config } }];

// Combines the two federal screening results into the boolean/flag INPUTS that
// Quickbase's 0-100 scoring formula consumes. The score itself is computed by
// Quickbase (a Formula - Numeric field), NOT here — see n8n/README.md.
const prep = $('Config & Prepare').first().json;
const p = prep.body;
const cfg = prep.config;

// The HTTP nodes may hand us either a parsed object or, when the API returns
// JSON under a non-JSON content type, the raw body as a string under `.data`.
// Normalise both shapes.
function parseBody(x) {
  if (x == null) return {};
  if (typeof x === 'string') {
    try { return JSON.parse(x); } catch (e) { return {}; }
  }
  if (typeof x.data === 'string') {
    try { return JSON.parse(x.data); } catch (e) { return {}; }
  }
  return x;
}
const sam = parseBody($('SAM.gov Exclusions').first().json);
const csl = parseBody($('Trade.gov CSL').first().json);

// SAM exclusions API returns { totalRecords, excludedEntity: [...] }.
const samTotal = Number(
  sam.totalRecords != null
    ? sam.totalRecords
    : Array.isArray(sam.excludedEntity)
    ? sam.excludedEntity.length
    : NaN
);
// Trade.gov CSL search API returns { total, results: [...] }.
const cslTotal = Number(
  csl.total != null ? csl.total : Array.isArray(csl.results) ? csl.results.length : NaN
);

// If either response is missing its expected shape, the check failed. Flag for
// manual review rather than silently treating a failed check as "clear".
const screeningIncomplete = Number.isNaN(samTotal) || Number.isNaN(cslTotal);

const samExclusionHit = samTotal > 0;
const ofacHit = cslTotal > 0;
const docKeys = (p.documents || []).map((d) => d.key);

const screening = {
  samExclusionHit,
  ofacHit,
  samMatchCount: Number.isNaN(samTotal) ? null : samTotal,
  ofacMatchCount: Number.isNaN(cslTotal) ? null : cslTotal,
  // A name match can be a false positive; treat it as a hard flag for a human
  // to clear, not an automatic permanent rejection.
  disqualifierFlag: samExclusionHit || ofacHit,
  screeningIncomplete,
  msaDigitallySigned: p.attestation === true,
  financialsUploaded: docKeys.includes('financials'),
  cfseCurrent: docKeys.includes('cfse'),
  coiUploaded: docKeys.includes('coi'),
  referencesProvided: (p.references || []).filter((r) => r && r.name).length,
};

return [{ json: { payload: p, config: cfg, screening } }];

// Builds the Quickbase "create record" body. Fetches each compliance PDF from
// its Vercel Blob URL and base64-encodes it for the file-attachment field.
// Requires an n8n whose Code node exposes this.helpers.httpRequest (v1.x+).
const ev = $('Evaluate Screening').first().json;
const p = ev.payload;
const s = ev.screening;
const cfg = ev.config;
const F = cfg.fieldMap;
const FF = cfg.fileFieldMap;

const rec = {};
const set = (fid, value) => {
  if (fid != null && value !== undefined) rec[fid] = { value };
};
const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// --- Vendor / capacity fields ---
// Quickbase "Entity Type" is a restricted choice field; translate the form's
// short codes to its exact option labels.
const ENTITY_LABELS = {
  sole: 'Sole Proprietor',
  partnership: 'Partnership',
  llc: 'LLC',
  corp: 'Corporation',
};

set(F.companyName, p.companyName);
set(F.trade, p.trade);
set(F.entityType, ENTITY_LABELS[p.entityType] || p.entityType);
set(F.ownerName, p.ownerName);
set(F.ein, p.ein);
set(F.licenseNumber, p.licenseNumber);
set(F.dacoReg, p.dacoReg);
set(F.streetAddress, p.streetAddress);
set(F.city, p.city);
set(F.state, p.state);
set(F.zip, p.zip);
set(F.municipio, p.municipio);
set(F.yearsInBusiness, num(p.yearsInBusiness));
set(F.revenue, num(p.revenue));
set(F.activeCrews, num(p.activeCrews));
set(F.bondSingle, num(p.bondSingle));
set(F.canMeetVolume, !!p.canMeetVolume);
set(F.hasLineOfCredit, !!p.hasLineOfCredit);
set(F.bonded, !!p.bonded);

// --- Contacts ---
set(F.contactName, p.contactName);
set(F.contactEmail, p.contactEmail);
set(F.contactPhone, p.contactPhone);
set(F.accountingName, p.accountingName);
set(F.accountingEmail, p.accountingEmail);
set(F.accountingPhone, p.accountingPhone);

// --- Signers: full set as JSON text, plus flattened first-signer fields ---
const signers = Array.isArray(p.signers) ? p.signers : [];
set(F.signers, JSON.stringify(signers));
set(F.signerCount, signers.length);
set(F.digitalSignatureName, signers[0] && signers[0].name);
set(F.signerTitle, signers[0] && signers[0].title);
set(F.personalGuarantee, p.personalGuarantee === true);
set(F.executedAt, p.executedAt);
// Initial workflow status (restricted choice field).
set(F.status, s.disqualifierFlag || s.screeningIncomplete ? 'Under Review' : 'Pending');

// --- Screening / scoring inputs (federal, automated) ---
set(F.samExclusionHit, s.samExclusionHit);
set(F.ofacHit, s.ofacHit);
// Disqualifier Flag is a Quickbase formula field (derived from the hits above).
set(F.screeningIncomplete, s.screeningIncomplete);
set(F.msaDigitallySigned, s.msaDigitallySigned);
set(F.financialsUploaded, s.financialsUploaded);
set(F.cfseCurrent, s.cfseCurrent);

// --- Scoring inputs that require MANUAL PR-compliance review. Defaulted
//     conservatively so the initial Quickbase score stays low until a reviewer
//     verifies them (PR govt portals can't be scraped — see project notes). ---
set(F.meetsInsuranceLimits, false);
set(F.verifiedReferences, 0);
set(F.entityStanding, 'Pending Review');
set(F.dacoComplaints, 0);
set(F.materialLawsuits, 0);

// --- Fetch + attach compliance PDFs from their Vercel Blob URLs ---
for (const d of p.documents || []) {
  const fid = FF[d.key];
  if (!fid || !d.url) continue;
  const buf = await this.helpers.httpRequest({ url: d.url, encoding: 'arraybuffer' });
  const data = Buffer.from(buf).toString('base64');
  rec[fid] = { value: { fileName: d.filename || d.key + '.pdf', data } };
}

return [
  {
    json: {
      qbBody: { to: cfg.quickbaseTableId, data: [rec] },
      documents: p.documents || [],
      screening: s,
    },
  },
];

// Summarises the result for the synchronous webhook response sent back to the
// Next.js /api/submit handler.
//
// IMPORTANT: Quickbase returns HTTP 200 even when a record is NOT created (it
// reports per-row problems in metadata.lineErrors). So success is determined by
// an actual created record id, not by the HTTP status.
const qb = $input.first().json || {};
const built = $('Build Quickbase Record').first().json;
const md = qb.metadata || {};
const recId =
  Array.isArray(md.createdRecordIds) && md.createdRecordIds.length
    ? md.createdRecordIds[0]
    : null;
const lineErrors = md.lineErrors || null;
const created = recId !== null;

return [
  {
    json: {
      ok: created,
      quickbaseRecordId: recId,
      quickbaseLineErrors: lineErrors,
      // A non-created record is always "flagged"; a created one is flagged when
      // screening hit something or could not be completed.
      flagged: created
        ? built.screening.disqualifierFlag || built.screening.screeningIncomplete
        : true,
      screening: built.screening,
      documents: built.documents,
    },
  },
];

// Fans the staged documents out to one item each so the next node can DELETE
// each Vercel Blob. Emits nothing when there were no uploads (cleanup skipped).
return ($json.documents || []).map((d) => ({ json: d }));
